function cyrChunk(t){t=t.replace(/[’‘ʻʼ`´]/g,"'");let o='';for(let i=0;i<t.length;){const l2=t.substr(i,2).toLowerCase(),ch=t[i],lo=ch.toLowerCase(),pl=i>0&&/[A-Za-z']/.test(t[i-1]);let r,adv=1;
 if(CD[l2]){r=CD[l2];adv=2}else if(lo==='e'&&!pl)r='э';else if(CS[lo])r=CS[lo];else{o+=ch;i++;continue}
 o+=(ch!==lo&&/[A-Z]/.test(ch))?r.toUpperCase():r;i+=adv}return o}
