const LANGS=[['uz',"O'zbekcha"],['uzc','Ўзбекча'],['ru','Русский'],['en','English']];
let LANG='uz';
function setLang(l){LANG=l}
function t(k,p){let s;
 if(LANG==='uzc')s=translit(DICT.uz[k]!=null?DICT.uz[k]:k);
 else s=(DICT[LANG]&&DICT[LANG][k])!=null?DICT[LANG][k]:(DICT.uz[k]!=null?DICT.uz[k]:k);
 return p?s.replace(/\{(\w+)\}/g,(_,x)=>p[x]!=null?p[x]:''):s}
